The pair $({\hat{\alpha}}, {\hat{\nu}})$ defined above satisfies the following three properties:
    \begin{enumerate}
      \item[(i)] It holds that $ {\hat{\nu}_{S}}\in \partial \lVert{\hat{\alpha}_{S}}\rVert_1;$
      \item[(ii)] If $\lVert{\hat{\nu}_{{S}^c}}\rVert_{\infty}<1$, then any solution ${\hat{\beta}}$ to the problem~(2) satisfies \textnormal{supp}$({\hat{\beta}})\subset S$;
      \item[(iii)] Under Assumption~1 and $\lVert{\hat{\nu}_{{S}^c}}\rVert_{\infty}<1$, the solution ${\hat{\beta}}$ is unique, and ${\hat{\beta}} = {\hat{\alpha}}=({\hat{\alpha}_{S}}^\top,{\hat{\alpha}_{{S}^c}}^\top)^\top\in {\mathbb{R}}^p$.
    \end{enumerate}

Under Assumption~1 and~2,
  the following properties hold on the event $\mathcal{T}_{{\lambda}}$.
  \begin{enumerate}
    \item[(a)] $\ell_{\infty}$-bound: $\lVert{\hat{\beta}}_{{\lambda}}-{\beta^*}\rVert_{\infty}\leq 1.5a{\lambda}/c_{\min}$\,;
    \item[(b)] support recovery: $\textnormal{supp}({\hat{\beta}}_{{\lambda}})\subset S$, and $\textnormal{supp}({\hat{\beta}}_{{\lambda}}) = S$ if $\min_{j \in S}|{\beta^*_j}|>1.5a{\lambda}/c_{\min}$\,.


  \end{enumerate}
